    def create_proctor(proctor: Proctor):
        cursor.execute('INSERT INTO proctors VALUES (?, ?, ?, ?)', 
                        (proctor.id, proctor.username, proctor.password, int(proctor.status)))
        conn.commit()

    @staticmethod
    def get_proctor(id: int):
        cursor.execute('SELECT * FROM proctors WHERE id = ?', (id,))
        return cursor.fetchone()

    @staticmethod
    def update_proctor(id: int, proctor: Proctor):
        cursor.execute('UPDATE proctors SET username = ?, password = ?, status = ? WHERE id = ?', 
                        (proctor.username, proctor.password, int(proctor.status), id))
        conn.commit()

    @staticmethod
    def delete_proctor(id: int):
        cursor.execute('DELETE FROM proctors WHERE id = ?', (id,))
        conn.commit()

